def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse one field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the closing quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote character
                        field.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Check what follows
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                                fields.append(''.join(field))
                                break
                            else:
                                # Invalid: closing quote not followed by comma or end
                                return None
                        else:
                            # End of line
                            fields.append(''.join(field))
                            break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Invalid: unquoted field contains double quote
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < len(line):
                # Skip the comma
                i += 1

    return fields

